        );
        Set<String> result = new LinkedHashSet<>();
        if (!line.isEmpty()) {
            for (String api : line.split("\\s+")) {
                result.add(api + "=" + mapping.getOrDefault(api, "REVIEW"));
            }
        }
        System.out.println(String.join(",", result));
    }
}

